## Building a Text Analyzer

### Character Frequency with Vec

```xiom
fn char_frequency(text: Str) {
  let mut counts: Vec[Int] = Vec[Int].new();
  let mut i = 0;
  while i < 26 { counts.push(0); i += 1; };

  let mut j = 0;
  while j < text.len() {
    let c = text.get(j).unwrap();
    if c >= 'a' && c <= 'z' {
      let idx = c as Int - 'a' as Int;
      let old = counts.get(idx).unwrap();
      counts.set(idx, old + 1);
    };
    j += 1;
  };

  let mut k = 0;
  while k < 26 {
    let letter = ('a' as Int + k) as Char;
    let count = counts.get(k).unwrap();
    if count > 0 {
      io.println(letter);
      io.println(count);
    };
    k += 1;
  };
}
```

### Most Common Letter

```xiom
fn most_common_char(text: Str) -> Char {
  let mut counts: Vec[Int] = Vec[Int].new();
  let mut i = 0;
  while i < 26 { counts.push(0); i += 1; };

  let mut j = 0;
  while j < text.len() {
    let c = text.get(j).unwrap();
    if c >= 'a' && c <= 'z' {
      let idx = c as Int - 'a' as Int;
      counts.set(idx, counts.get(idx).unwrap() + 1);
    };
    j += 1;
  };

  let mut max_idx = 0;
  let mut k = 1;
  while k < 26 {
    if counts.get(k).unwrap() > counts.get(max_idx).unwrap() {
      max_idx = k;
    };
    k += 1;
  };

  ('a' as Int + max_idx) as Char
}
```

