use xiom.io;
fn letter_frequency(text: Str) -> Vec[Int] {
  let mut counts: Vec[Int] = Vec[Int].new();
  let mut i = 0;
  while i < 26 { counts.push(0); i += 1; };
  let mut j = 0;
  while j < text.len() {
    let c = text.get(j).unwrap();
    if c >= 'a' && c <= 'z' {
      let idx = c as Int - 'a' as Int;
      counts.set(idx, counts.get(idx).unwrap() + 1);
    };
    j += 1;
  };
  counts
}

fn most_frequent_letter(text: Str) -> Char {
  let counts = letter_frequency(text);
  let mut max_idx = 0;
  let mut i = 1;
  while i < 26 {
    if counts.get(i).unwrap() > counts.get(max_idx).unwrap() {
      max_idx = i;
    };
    i += 1;
  };
  ('a' as Int + max_idx) as Char
}

fn main() -> Int {
  io.println(most_frequent_letter("hello world").to_str());
  return 0;
}
